package com.example.sgva.infrastructure.parsing

import com.example.sgva.domain.FormatoArchivoInvalidoException
import de.siegmar.fastcsv.reader.CsvReader
import org.springframework.stereotype.Component
import java.io.ByteArrayInputStream
import java.nio.charset.StandardCharsets

/**
 * Adaptador de [com.example.sgva.domain.DocumentParserPort] para archivos `.csv`,
 * implementado sobre FastCSV (`DESIGN_SGVA.md` §4, adaptador «OpenCsvParser» del
 * diseño; se usa FastCSV por ser una dependencia sin transitivas y gestionable
 * dentro del stack de Spring Boot 4).
 *
 * Se lee la primera fila no vacía como encabezado; la normalización de los
 * valores la aplica [ParserDocumentalBase] a través de los mapeadores.
 */
@Component
internal class CsvDocumentParser : ParserDocumentalBase() {

    override fun soporta(nombreArchivo: String): Boolean = extension(nombreArchivo) == "csv"

    override fun leerTabla(contenido: ByteArray): TablaCruda {
        val registros = CsvReader.builder()
            .skipEmptyLines(true)
            .ofCsvRecord(ByteArrayInputStream(contenido), StandardCharsets.UTF_8)
            .use { lector -> lector.map { it.fields } }

        if (registros.isEmpty()) {
            throw FormatoArchivoInvalidoException("El archivo CSV no contiene ninguna fila.")
        }

        return TablaCruda(
            encabezados = registros.first().map(String::trim),
            filas = registros.drop(1),
        )
    }

    private fun extension(nombreArchivo: String): String =
        nombreArchivo.substringAfterLast('.', "").lowercase()
}

package com.example.sgva.infrastructure.parsing

import com.example.sgva.domain.FormatoArchivoInvalidoException
import org.apache.poi.ss.usermodel.Cell
import org.apache.poi.ss.usermodel.CellType
import org.apache.poi.ss.usermodel.Row
import org.apache.poi.xssf.usermodel.XSSFWorkbook
import org.springframework.stereotype.Component
import java.io.ByteArrayInputStream

/**
 * Adaptador de [com.example.sgva.domain.DocumentParserPort] para archivos `.xlsx`,
 * implementado sobre Apache POI (`DESIGN_SGVA.md` §4, adaptador «ApachePoiExcelParser»).
 *
 * Se procesa la primera hoja del libro: la primera fila es el encabezado y el
 * resto son datos. Las celdas numéricas se convierten a texto sin el `.0` que
 * añade Excel a los enteros; la normalización final la aplica [ParserDocumentalBase].
 */
@Component
internal class ExcelDocumentParser : ParserDocumentalBase() {

    override fun soporta(nombreArchivo: String): Boolean =
        nombreArchivo.substringAfterLast('.', "").lowercase() == "xlsx"

    override fun leerTabla(contenido: ByteArray): TablaCruda =
        XSSFWorkbook(ByteArrayInputStream(contenido)).use { libro ->
            if (libro.numberOfSheets == 0) {
                throw FormatoArchivoInvalidoException("El archivo Excel no contiene ninguna hoja.")
            }

            val filas = libro.getSheetAt(0).iterator().asSequence().toList()
            if (filas.isEmpty()) {
                throw FormatoArchivoInvalidoException("La primera hoja del archivo Excel está vacía.")
            }

            val encabezados = leerFila(filas.first()).map(String::trim)
            TablaCruda(
                encabezados = encabezados,
                filas = filas.drop(1)
                    .map { leerFila(it, encabezados.size) }
                    .filter { valores -> valores.any { it.isNotBlank() } },
            )
        }

    private fun leerFila(fila: Row, columnasMinimas: Int = 0): List<String> {
        val columnas = maxOf(fila.lastCellNum.toInt(), columnasMinimas)
        return (0 until columnas).map { indice ->
            valorComoTexto(fila.getCell(indice, Row.MissingCellPolicy.RETURN_BLANK_AS_NULL))
        }
    }

    private fun valorComoTexto(celda: Cell?): String = when {
        celda == null -> ""
        celda.cellType == CellType.STRING -> celda.stringCellValue.trim()
        celda.cellType == CellType.BOOLEAN -> celda.booleanCellValue.toString()
        celda.cellType == CellType.NUMERIC -> numeroComoTexto(celda.numericCellValue)
        celda.cellType == CellType.FORMULA -> when (celda.cachedFormulaResultType) {
            CellType.STRING -> celda.stringCellValue.trim()
            CellType.NUMERIC -> numeroComoTexto(celda.numericCellValue)
            CellType.BOOLEAN -> celda.booleanCellValue.toString()
            else -> ""
        }
        else -> ""
    }

    private fun numeroComoTexto(valor: Double): String =
        if (valor % 1.0 == 0.0) valor.toLong().toString() else valor.toString()
}

package com.example.sgva.infrastructure.parsing

import com.example.sgva.domain.Docente
import com.example.sgva.domain.DocumentParserPort
import com.example.sgva.domain.Estudiante
import com.example.sgva.domain.EvaluacionDocumental
import com.example.sgva.domain.FormatoArchivoInvalidoException
import com.example.sgva.domain.ResultadoEncuestaPregunta
import com.example.sgva.domain.RespuestaEncuesta

/**
 * Base común de los adaptadores de [DocumentParserPort]. Concentra el
 * *Protocolo de Validación en Origen* (`DESIGN_SGVA.md` §5):
 *
 *  1. Cada adaptador concreto solo se encarga de leer el archivo a una
 *     [TablaCruda] (encabezados + filas de texto) según su formato físico.
 *  2. Esta base verifica que estén todas las columnas obligatorias de la entidad.
 *  3. Mapea y normaliza fila por fila; cualquier fallo se envuelve en
 *     [FormatoArchivoInvalidoException] indicando el archivo y la fila, sin dejar
 *     escapar excepciones técnicas de la librería de parseo.
 */
internal abstract class ParserDocumentalBase : DocumentParserPort {

    /**
     * Lee el archivo a una tabla de texto. Puede lanzar excepciones técnicas de
     * la librería subyacente: [transformar] las traduce a excepción controlada.
     */
    protected abstract fun leerTabla(contenido: ByteArray): TablaCruda

    final override fun extraerEstudiantes(nombreArchivo: String, contenido: ByteArray): List<Estudiante> =
        transformar(nombreArchivo, contenido, MapeadorEstudiante)

    final override fun extraerDocentes(nombreArchivo: String, contenido: ByteArray): List<Docente> =
        transformar(nombreArchivo, contenido, MapeadorDocente)

    final override fun extraerRespuestasEncuestas(nombreArchivo: String, contenido: ByteArray): List<RespuestaEncuesta> =
        transformar(nombreArchivo, contenido, MapeadorRespuestaEncuesta)

    final override fun extraerResultadosEncuestaPregunta(
        nombreArchivo: String,
        contenido: ByteArray,
    ): List<ResultadoEncuestaPregunta> = transformar(nombreArchivo, contenido, MapeadorResultadoEncuestaPregunta)

    final override fun extraerEvaluacionesDocumentales(
        nombreArchivo: String,
        contenido: ByteArray,
    ): List<EvaluacionDocumental> = transformar(nombreArchivo, contenido, MapeadorEvaluacionDocumental)

    private fun <T> transformar(
        nombreArchivo: String,
        contenido: ByteArray,
        mapeador: MapeadorEntidad<T>,
    ): List<T> {
        val tabla = leerTablaControlada(nombreArchivo, contenido)
        exigirColumnas(nombreArchivo, tabla.encabezados, mapeador.columnasObligatorias)

        return tabla.filas.mapIndexed { indice, valores ->
            val numeroFila = indice + 2 // +1 por el encabezado, +1 para numeración en base 1
            val fila = tabla.encabezados.zip(valores).toMap()
            try {
                mapeador.mapear(fila)
            } catch (datoInvalido: IllegalArgumentException) {
                // Cubre también NumberFormatException (subtipo) y las excepciones de dominio.
                throw FormatoArchivoInvalidoException(
                    "Archivo '$nombreArchivo', fila $numeroFila: ${datoInvalido.message}",
                    datoInvalido,
                )
            }
        }
    }

    private fun leerTablaControlada(nombreArchivo: String, contenido: ByteArray): TablaCruda =
        try {
            leerTabla(contenido)
        } catch (formatoInvalido: FormatoArchivoInvalidoException) {
            throw formatoInvalido
        } catch (falloTecnico: Exception) {
            throw FormatoArchivoInvalidoException(
                "No se pudo leer el archivo '$nombreArchivo': ${falloTecnico.message}",
                falloTecnico,
            )
        }

    private fun exigirColumnas(
        nombreArchivo: String,
        encabezados: List<String>,
        obligatorias: Set<String>,
    ) {
        val presentes = encabezados.map { it.trim() }.toSet()
        val faltantes = (obligatorias - presentes).sorted()
        if (faltantes.isNotEmpty()) {
            throw FormatoArchivoInvalidoException(
                "Al archivo '$nombreArchivo' le faltan columnas obligatorias: ${faltantes.joinToString(", ")}.",
            )
        }
    }
}

package com.example.sgva.infrastructure.parsing

import com.example.sgva.domain.EstadoEstudiante
import com.example.sgva.domain.FormatoArchivoInvalidoException
import com.example.sgva.domain.NivelFormacion
import com.example.sgva.domain.TipoDedicacion
import com.example.sgva.domain.TipoEstamento
import org.junit.jupiter.api.Test
import org.junit.jupiter.api.assertThrows
import kotlin.test.assertEquals
import kotlin.test.assertNull
import kotlin.test.assertTrue

class CsvDocumentParserTest {

    private val parser = CsvDocumentParser()

    @Test
    fun `soporta solo archivos con extension csv`() {
        assertTrue(parser.soporta("datos_estudiantes.csv"))
        assertTrue(parser.soporta("RUTA/Datos.CSV"))
        assertTrue(!parser.soporta("datos.xlsx"))
    }

    @Test
    fun `extrae los estudiantes del fixture y trata la celda vacia de puntaje como null`() {
        val estudiantes = parser.extraerEstudiantes("datos_estudiantes_test.csv", fixture("datos_estudiantes_test.csv"))

        assertEquals(10, estudiantes.size)
        val primero = estudiantes.first()
        assertEquals("2021101", primero.id)
        assertEquals("20211", primero.cohorte)
        assertEquals(EstadoEstudiante.GRADUADO, primero.estado)
        assertEquals(210, primero.puntajeSaberPro)
        assertNull(estudiantes[2].puntajeSaberPro)
    }

    @Test
    fun `normaliza el periodo con guion de los docentes al formato AAAAS`() {
        val docentes = parser.extraerDocentes("datos_docentes_test.csv", fixture("datos_docentes_test.csv"))

        assertEquals(4, docentes.size)
        assertTrue(docentes.all { it.periodo == "20261" })
        assertTrue(docentes.all { it.programa == "EGSTI" })
        assertEquals(NivelFormacion.DOCTORADO, docentes.first().nivelFormacion)
        assertEquals(TipoDedicacion.MEDIO_TIEMPO, docentes.last().dedicacion)
    }

    @Test
    fun `extrae las respuestas de encuesta del fixture y normaliza el periodo con guion`() {
        val respuestas =
            parser.extraerRespuestasEncuestas("datos_encuestas_test.csv", fixture("datos_encuestas_test.csv"))

        assertEquals(5, respuestas.size)
        assertTrue(respuestas.all { it.periodo == "20261" })
        val primera = respuestas.first()
        assertEquals("R001", primera.id)
        assertEquals(TipoEstamento.ESTUDIANTE, primera.estamento)
        assertEquals("Plan de Estudios", primera.factor)
        assertEquals(5, primera.calificacion)
        assertEquals(TipoEstamento.EMPLEADOR, respuestas.last().estamento)
    }

    @Test
    fun `extrae los resultados de encuesta por pregunta del fixture, normaliza el periodo y trata N A como promedio ausente`() {
        val resultados = parser.extraerResultadosEncuestaPregunta(
            "datos_resultados_encuesta_pregunta_test.csv",
            fixture("datos_resultados_encuesta_pregunta_test.csv"),
        )

        assertEquals(4, resultados.size)
        assertTrue(resultados.all { it.periodo == "20261" })
        assertTrue(resultados.all { it.programa == "EGSTI" })

        val primero = resultados[0]
        assertEquals(setOf(TipoEstamento.ESTUDIANTE), primero.estamentos)
        assertEquals(4.5, primero.promedio)

        val segundo = resultados[1]
        assertEquals(setOf(TipoEstamento.ESTUDIANTE, TipoEstamento.PROFESOR), segundo.estamentos)

        val tercero = resultados[2]
        assertNull(tercero.promedio)

        val cuarto = resultados[3]
        assertEquals(
            setOf(TipoEstamento.DIRECTIVO, TipoEstamento.ADMINISTRATIVO, TipoEstamento.ALIADO_ESTRATEGICO),
            cuarto.estamentos,
        )
    }

    @Test
    fun `rechaza un resultado de encuesta por pregunta con promedio igual a 0`() {
        val csv = """
            programa,periodo,codigoPregunta,caracteristica,estamentos,promedio
            EGSTI,20261,A1,1.1,ESTUDIANTE,0
        """.trimIndent().toByteArray()

        val error = assertThrows<FormatoArchivoInvalidoException> {
            parser.extraerResultadosEncuestaPregunta("datos.csv", csv)
        }
        assertTrue(error.message!!.contains("fila 2"))
    }

    @Test
    fun `rechaza un resultado de encuesta por pregunta con un estamento no reconocible`() {
        val csv = """
            programa,periodo,codigoPregunta,caracteristica,estamentos,promedio
            EGSTI,20261,A1,1.1,NO_EXISTE,4.5
        """.trimIndent().toByteArray()

        val error = assertThrows<FormatoArchivoInvalidoException> {
            parser.extraerResultadosEncuestaPregunta("datos.csv", csv)
        }
        assertTrue(error.message!!.contains("estamentos"))
    }

    @Test
    fun `extrae las evaluaciones documentales del fixture, normaliza el periodo y trata las columnas opcionales vacias como null`() {
        val evaluaciones = parser.extraerEvaluacionesDocumentales(
            "datos_evaluaciones_documentales_test.csv",
            fixture("datos_evaluaciones_documentales_test.csv"),
        )

        assertEquals(4, evaluaciones.size)
        assertTrue(evaluaciones.all { it.periodo == "20261" })
        assertTrue(evaluaciones.all { it.programa == "EGSTI" })

        val primera = evaluaciones[0]
        assertEquals(4.7, primera.calificacion)
        assertEquals("Evidencia documental consistente con el PEP", primera.justificacion)
        assertEquals("Actualizar el acta de autoevaluación", primera.sugerenciasMejora)

        val segunda = evaluaciones[1]
        assertNull(segunda.justificacion)
        assertEquals("Fortalecer el seguimiento estadístico", segunda.sugerenciasMejora)

        val tercera = evaluaciones[2]
        assertNull(tercera.sugerenciasMejora)
    }

    @Test
    fun `rechaza una evaluacion documental con calificacion N A, a diferencia del promedio de encuesta`() {
        val csv = """
            programa,caracteristica,periodo,calificacion
            EGSTI,1.1,20261,N/A
        """.trimIndent().toByteArray()

        val error = assertThrows<FormatoArchivoInvalidoException> {
            parser.extraerEvaluacionesDocumentales("datos.csv", csv)
        }
        assertTrue(error.message!!.contains("fila 2"))
    }

    @Test
    fun `rechaza una evaluacion documental con calificacion fuera de rango`() {
        val csv = """
            programa,caracteristica,periodo,calificacion
            EGSTI,1.1,20261,5.5
        """.trimIndent().toByteArray()

        val error = assertThrows<FormatoArchivoInvalidoException> {
            parser.extraerEvaluacionesDocumentales("datos.csv", csv)
        }
        assertTrue(error.message!!.contains("calificación documental"))
    }

    @Test
    fun `rechaza un csv de evaluaciones documentales al que le falta la columna calificacion`() {
        val csv = "programa,caracteristica,periodo\nEGSTI,1.1,20261\n".toByteArray()

        val error = assertThrows<FormatoArchivoInvalidoException> {
            parser.extraerEvaluacionesDocumentales("incompleto.csv", csv)
        }
        assertTrue(error.message!!.contains("calificacion"))
    }

    @Test
    fun `rechaza un csv al que le falta una columna obligatoria`() {
        val csv = "id,programa,facultad,estado\nE1,Sistemas,Ingeniería,MATRICULADO\n".toByteArray()

        val error = assertThrows<FormatoArchivoInvalidoException> {
            parser.extraerEstudiantes("incompleto.csv", csv)
        }
        assertTrue(error.message!!.contains("cohorte"))
    }

    @Test
    fun `rechaza un csv con un enum no reconocible senalando la fila`() {
        val csv = buildString {
            append("id,programa,facultad,cohorte,estado,puntajeSaberPro\n")
            append("E1,Sistemas,Ingeniería,20231,MATRICULADO,\n")
            append("E2,Sistemas,Ingeniería,20231,EGRESADO,\n")
        }.toByteArray()

        val error = assertThrows<FormatoArchivoInvalidoException> {
            parser.extraerEstudiantes("datos.csv", csv)
        }
        assertTrue(error.message!!.contains("fila 3"))
        assertTrue(error.message!!.contains("estado"))
    }

    private fun fixture(nombre: String): ByteArray =
        checkNotNull(javaClass.getResourceAsStream("/fixtures/$nombre")) { "falta el fixture $nombre" }
            .use { it.readBytes() }
}

package com.example.sgva.infrastructure.parsing

import com.example.sgva.domain.EstadoEstudiante
import com.example.sgva.domain.FormatoArchivoInvalidoException
import com.example.sgva.domain.TipoEstamento
import org.apache.poi.xssf.usermodel.XSSFWorkbook
import org.junit.jupiter.api.Test
import org.junit.jupiter.api.assertThrows
import java.io.ByteArrayOutputStream
import kotlin.test.assertEquals
import kotlin.test.assertNull
import kotlin.test.assertTrue

class ExcelDocumentParserTest {

    private val parser = ExcelDocumentParser()

    @Test
    fun `soporta solo archivos con extension xlsx`() {
        assertTrue(parser.soporta("planta_docente.xlsx"))
        assertTrue(!parser.soporta("planta_docente.csv"))
    }

    @Test
    fun `extrae estudiantes de un libro con celdas numericas y de texto`() {
        val libro = xlsx(
            listOf("id", "programa", "facultad", "cohorte", "estado", "puntajeSaberPro"),
            listOf("2023106", "Ingeniería de Sistemas", "Ingeniería", "2023-1", "matriculado", ""),
            listOf("2021101", "Ingeniería de Sistemas", "Ingeniería", 20211.0, "GRADUADO", 210.0),
        )

        val estudiantes = parser.extraerEstudiantes("estudiantes.xlsx", libro)

        assertEquals(2, estudiantes.size)
        assertEquals("20231", estudiantes[0].cohorte)
        assertEquals(EstadoEstudiante.MATRICULADO, estudiantes[0].estado)
        assertNull(estudiantes[0].puntajeSaberPro)
        assertEquals("2021101", estudiantes[1].id)
        assertEquals(210, estudiantes[1].puntajeSaberPro)
    }

    @Test
    fun `ignora las filas totalmente vacias`() {
        val libro = xlsx(
            listOf("id", "programa", "facultad", "nivelFormacion", "dedicacion", "periodo"),
            listOf("D001", "EGSTI", "Ingenieria", "DOCTORADO", "TIEMPO_COMPLETO", "2026-1"),
            listOf("", "", "", "", "", ""),
        )

        val docentes = parser.extraerDocentes("docentes.xlsx", libro)

        assertEquals(1, docentes.size)
        assertEquals("20261", docentes.first().periodo)
        assertEquals("EGSTI", docentes.first().programa)
    }

    @Test
    fun `extrae respuestas de encuesta de un libro con celdas numericas y de texto`() {
        val libro = xlsx(
            listOf("id", "estamento", "factor", "calificacion", "periodo"),
            listOf("R001", "estudiante", "Infraestructura", 4.0, "2026-1"),
            listOf("R002", "PROFESOR", "Plan de Estudios", "5", "20261"),
        )

        val respuestas = parser.extraerRespuestasEncuestas("encuestas.xlsx", libro)

        assertEquals(2, respuestas.size)
        assertEquals(TipoEstamento.ESTUDIANTE, respuestas[0].estamento)
        assertEquals(4, respuestas[0].calificacion)
        assertEquals("20261", respuestas[0].periodo)
        assertEquals(TipoEstamento.PROFESOR, respuestas[1].estamento)
    }

    @Test
    fun `extrae resultados de encuesta por pregunta de un libro con celdas numericas y de texto`() {
        val libro = xlsx(
            listOf("programa", "periodo", "codigoPregunta", "caracteristica", "estamentos", "promedio"),
            listOf("EGSTI", "2026-1", "A1", "1.1", "ESTUDIANTE;PROFESOR", 4.5),
            listOf("EGSTI", "2026-1", "A2", "1.2", "DIRECTIVO", "N/A"),
        )

        val resultados = parser.extraerResultadosEncuestaPregunta("resultados.xlsx", libro)

        assertEquals(2, resultados.size)
        assertEquals("20261", resultados[0].periodo)
        assertEquals(setOf(TipoEstamento.ESTUDIANTE, TipoEstamento.PROFESOR), resultados[0].estamentos)
        assertEquals(4.5, resultados[0].promedio)
        assertNull(resultados[1].promedio)
    }

    @Test
    fun `extrae evaluaciones documentales de un libro con celdas numericas y de texto`() {
        val libro = xlsx(
            listOf("programa", "caracteristica", "periodo", "calificacion", "justificacion"),
            listOf("EGSTI", "1.1", "2026-1", 4.7, "Evidencia documental consistente"),
            listOf("EGSTI", "1.2", "20261", "3,5", ""),
        )

        val evaluaciones = parser.extraerEvaluacionesDocumentales("evaluaciones.xlsx", libro)

        assertEquals(2, evaluaciones.size)
        assertEquals("20261", evaluaciones[0].periodo)
        assertEquals(4.7, evaluaciones[0].calificacion)
        assertEquals("Evidencia documental consistente", evaluaciones[0].justificacion)
        assertEquals(3.5, evaluaciones[1].calificacion)
        assertNull(evaluaciones[1].justificacion)
    }

    @Test
    fun `rechaza un libro corrupto con una excepcion controlada`() {
        val error = assertThrows<FormatoArchivoInvalidoException> {
            parser.extraerEstudiantes("corrupto.xlsx", "esto no es un xlsx".toByteArray())
        }
        assertTrue(error.message!!.contains("corrupto.xlsx"))
    }

    private fun xlsx(encabezados: List<String>, vararg filas: List<Any>): ByteArray =
        XSSFWorkbook().use { libro ->
            val hoja = libro.createSheet("datos")
            hoja.createRow(0).also { fila ->
                encabezados.forEachIndexed { i, titulo -> fila.createCell(i).setCellValue(titulo) }
            }
            filas.forEachIndexed { indiceFila, valores ->
                val fila = hoja.createRow(indiceFila + 1)
                valores.forEachIndexed { i, valor ->
                    val celda = fila.createCell(i)
                    when (valor) {
                        is Number -> celda.setCellValue(valor.toDouble())
                        else -> celda.setCellValue(valor.toString())
                    }
                }
            }
            ByteArrayOutputStream().use { salida ->
                libro.write(salida)
                salida.toByteArray()
            }
        }
}

